readback.query:
query ReadCreatedCharacter ($characterId: ID!) {
	character(id: $characterId) {
		backgroundText
		backstoryId
		createdAt
		ddbUrl
		description
		guildId
		id
		name
		ownerId
		pcxp
		regionId
		shortCode
		status
		updatedAt
		verificationStatus
		verificationSubmittedAt
	}
	myCharacters {
		items {
			id
		}
		total
	}
}

query {
	creationCatalog(filters: {kind:"background"}) {
		items {
			id
			kind
			name
			description
			introducedByRegionId
			available
			retired
		}
		total
	}
}

